/**
 * Canonicalize a video URL.
 * @param {string} url
 * @param {{ keepP?: boolean, keepTimestamp?: boolean }} [opts]
 *   keepP        - keep Bilibili part (?p=) and YouTube &index= (single-link mode)
 *   keepTimestamp- keep t=/start= timestamp params
 * @returns {string}
 */
export function canonicalizeVideoUrl(url, opts = {}) {
  const { keepP = false, keepTimestamp = false } = opts;
  if (!url || typeof url !== 'string') return url;
  try {
    const u = new URL(url);
    const host = u.hostname;
    const tParam = u.searchParams.get('t') || u.searchParams.get('start');

    // YouTube (watch + shorts)
    if (host.includes('youtube.com')) {
      if (u.pathname === '/watch') {
        const id = u.searchParams.get('v');
        if (!id) return url;
        let out = `https://www.youtube.com/watch?v=${id}`;
        if (keepP && u.searchParams.get('index')) out += `&index=${u.searchParams.get('index')}`;
        if (keepTimestamp && tParam) out += `&t=${tParam}`;
        return out;
      }
      if (u.pathname.startsWith('/shorts/')) {
        const id = u.pathname.split('/').filter(Boolean)[1];
        let out = `https://www.youtube.com/shorts/${id}`;
        if (keepTimestamp && tParam) out += `?t=${tParam}`;
        return out;
      }
      return url;
    }
    if (host.includes('youtu.be')) {
      const id = u.pathname.replace(/^\/+/, '').split('/')[0];
      if (!id) return url;
      let out = `https://www.youtube.com/watch?v=${id}`;
      if (keepTimestamp && tParam) out += `&t=${tParam}`;
      return out;
    }

    // Bilibili (handle ?bvid= watchlater links, keep part/timestamp on request)
    if (host.includes('bilibili.com')) {
      const bvid = u.searchParams.get('bvid');
      let pathname = u.pathname.replace(/\/$/, '');
      if (bvid && !/\/video\/BV/i.test(pathname)) pathname = `/video/${bvid}`;
      let out = u.origin + pathname;
      const parts = [];
      if (keepP && u.searchParams.get('p')) parts.push(`p=${u.searchParams.get('p')}`);
      if (keepTimestamp && u.searchParams.get('t')) parts.push(`t=${u.searchParams.get('t')}`);
      if (parts.length) out += `?${parts.join('&')}`;
      return out;
    }

    // Douyin / TikTok: normalize to origin + pathname + query (drop hash fragment)
    if (host.includes('douyin.com') || host.includes('tiktok.com')) {
      return `${u.origin}${u.pathname}${u.search}`;
    }

    // Other platforms: passthrough
    return url;
  } catch {
    return url;
  }
}

/** Append a timestamp (seconds) to a YouTube/Bilibili URL. Other hosts returned unchanged. */
export function appendTimestamp(url, seconds) {
  if (!url || !Number.isFinite(seconds) || seconds <= 0) return url;
  const t = Math.floor(seconds);
  try {
    if (url.includes('youtube.com') || url.includes('youtu.be')) {
      const u = new URL(url);
      u.searchParams.set('t', `${t}s`);
      return u.toString();
    }
    if (url.includes('bilibili.com')) {
      const u = new URL(url);
      u.searchParams.set('t', String(t));
      return u.toString();
    }
  } catch {
    return url;
  }
  return url;
}

/** Remove timestamp params (t=, start=) from a URL. */
export function stripTimestamp(url) {
  if (!url) return url;
  try {
    const u = new URL(url);
    u.searchParams.delete('t');
    u.searchParams.delete('start');
    u.searchParams.delete('time_continue');
    return u.toString();
  } catch {
    return url;
  }
}

/** Format seconds as H:MM:SS or M:SS. */
export function formatTimestamp(seconds) {
  if (!Number.isFinite(seconds) || seconds < 0) return '0:00';
  const s = Math.floor(seconds);
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const sec = s % 60;
  const mm = h > 0 ? String(m).padStart(2, '0') : String(m);
  return (h > 0 ? `${h}:` : '') + `${mm}:${String(sec).padStart(2, '0')}`;
}
